function toFileName(name) {
  return name.toLowerCase().replace(/['']/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') + '.json';
}

let written = 0, skipped = 0;
for (const t of techs) {
  const fname = toFileName(t.name);
  const fpath = path.join(outDir, fname);
  if (fs.existsSync(fpath)) { skipped++; continue; }
  fs.writeFileSync(fpath, JSON.stringify(t, null, 2) + '\n');
  written++;
}
console.log(`Tech supplement: wrote ${written}, skipped ${skipped}`);
console.log(`Total technology files now: ${fs.readdirSync(outDir).length}`);
